-- Captured from shipped MenFit v1 before the Keto/provider-ID migrations.
CREATE TABLE "activities" ("id" TEXT NOT NULL, "activity_type" TEXT NOT NULL, "title" TEXT NOT NULL, "notes" TEXT NULL, "started_at" INTEGER NOT NULL, "moving_time_ms" INTEGER NOT NULL, "elapsed_time_ms" INTEGER NOT NULL, "distance_meters" REAL NOT NULL, "elevation_gain_meters" REAL NULL, "avg_heart_rate" INTEGER NULL, "source" TEXT NOT NULL, "route_id" TEXT NULL, "metadata_json" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "activity_samples" ("id" TEXT NOT NULL, "activity_id" TEXT NOT NULL REFERENCES activities (id), "timestamp_ms" INTEGER NOT NULL, "latitude" REAL NOT NULL, "longitude" REAL NOT NULL, "elevation_meters" REAL NULL, "horizontal_accuracy_meters" REAL NULL, "heart_rate" INTEGER NULL, "is_paused" INTEGER NOT NULL DEFAULT 0 CHECK ("is_paused" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "badge_awards" ("id" TEXT NOT NULL, "badge_id" TEXT NOT NULL, "tier_key" TEXT NOT NULL, "awarded_at" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("badge_id", "tier_key"));
CREATE TABLE "challenges" ("id" TEXT NOT NULL, "kind" TEXT NOT NULL, "activity_types" TEXT NOT NULL, "target_units" INTEGER NOT NULL, "window_start" TEXT NOT NULL, "window_end" TEXT NOT NULL, "salt" INTEGER NOT NULL, "self_display_name" TEXT NOT NULL, "origin" TEXT NOT NULL, "author_tag" INTEGER NOT NULL, "buddy_display_name" TEXT NULL, "buddy_progress_percent" REAL NULL, "buddy_as_of" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "daily_checkins" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "energy" INTEGER NULL, "sleep" INTEGER NULL, "soreness" INTEGER NULL, "stress" INTEGER NULL, "pain" INTEGER NULL, "symptoms" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "daily_step_totals" ("day" TEXT NOT NULL, "steps" INTEGER NOT NULL, "source" TEXT NULL, "synced_at" INTEGER NOT NULL, PRIMARY KEY ("day"));
CREATE TABLE "flare_events" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "end_day" TEXT NULL, "severity" TEXT NOT NULL, "symptoms" TEXT NOT NULL DEFAULT '', "impact" TEXT NOT NULL, "category" TEXT NULL, "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "foods" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "brand" TEXT NULL, "serving_description" TEXT NOT NULL, "serving_grams" REAL NULL, "serving_volume_ml" REAL NULL, "calories_kcal" REAL NOT NULL, "protein_grams" REAL NOT NULL, "carbs_grams" REAL NOT NULL, "fat_grams" REAL NOT NULL, "iron_mg" REAL NULL, "saturated_fat_grams" REAL NULL, "trans_fat_grams" REAL NULL, "monounsaturated_fat_grams" REAL NULL, "polyunsaturated_fat_grams" REAL NULL, "fiber_grams" REAL NULL, "sugars_grams" REAL NULL, "added_sugars_grams" REAL NULL, "sodium_mg" REAL NULL, "potassium_mg" REAL NULL, "cholesterol_mg" REAL NULL, "calcium_mg" REAL NULL, "vitamin_d_mcg" REAL NULL, "vitamin_c_mg" REAL NULL, "barcode" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'custom', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "nutrition_entries" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "meal" TEXT NOT NULL, "food_id" TEXT NULL, "food_name" TEXT NOT NULL, "food_brand" TEXT NULL, "serving_description" TEXT NULL, "quantity_servings" REAL NOT NULL, "quantity_amount" REAL NOT NULL DEFAULT 1.0, "quantity_unit" TEXT NOT NULL DEFAULT 'serving', "serving_grams" REAL NULL, "serving_volume_ml" REAL NULL, "calories_kcal" REAL NOT NULL, "protein_grams" REAL NOT NULL, "carbs_grams" REAL NOT NULL, "fat_grams" REAL NOT NULL, "iron_mg" REAL NULL, "saturated_fat_grams" REAL NULL, "trans_fat_grams" REAL NULL, "monounsaturated_fat_grams" REAL NULL, "polyunsaturated_fat_grams" REAL NULL, "fiber_grams" REAL NULL, "sugars_grams" REAL NULL, "added_sugars_grams" REAL NULL, "sodium_mg" REAL NULL, "potassium_mg" REAL NULL, "cholesterol_mg" REAL NULL, "calcium_mg" REAL NULL, "vitamin_d_mcg" REAL NULL, "vitamin_c_mg" REAL NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "nutrition_goals" ("id" TEXT NOT NULL, "calorie_target_kcal" INTEGER NULL, "protein_target_grams" REAL NULL, "carb_target_grams" REAL NULL, "fat_target_grams" REAL NULL, "macro_target_mode" TEXT NOT NULL DEFAULT 'grams', "protein_target_percent" REAL NULL, "carb_target_percent" REAL NULL, "fat_target_percent" REAL NULL, "macro_locks" TEXT NOT NULL DEFAULT '', "hide_calorie_numbers" INTEGER NOT NULL DEFAULT 0 CHECK ("hide_calorie_numbers" IN (0, 1)), "activity_level" TEXT NULL, "weight_goal" TEXT NOT NULL DEFAULT 'maintain', "daily_deficit_kcal" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "recovery_days" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "routes" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "distance_meters" REAL NOT NULL, "estimated_duration_seconds" INTEGER NULL, "ascent_meters" REAL NULL, "descent_meters" REAL NULL, "geometry" TEXT NOT NULL, "activity_type" TEXT NOT NULL, "source" TEXT NOT NULL DEFAULT 'suggested', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "strength_cycles" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "routines_json" TEXT NOT NULL, "current_day_index" INTEGER NOT NULL DEFAULT 0, "total_sessions_completed" INTEGER NOT NULL DEFAULT 0, "total_volume_lifted_kg" REAL NOT NULL DEFAULT 0.0, "is_active" INTEGER NOT NULL DEFAULT 0 CHECK ("is_active" IN (0, 1)), "started_at" INTEGER NULL, "last_completed_at" INTEGER NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "strength_routines" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "exercises_json" TEXT NOT NULL, "estimated_duration_minutes" INTEGER NOT NULL DEFAULT 45, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "user_profiles" ("id" TEXT NOT NULL, "display_name" TEXT NOT NULL, "unit_system" TEXT NOT NULL, "weekly_activity_goal" INTEGER NULL, "date_of_birth" TEXT NULL, "height_cm" REAL NULL, "weight_kg" REAL NULL, "fitness_goal" TEXT NULL, "running_experience" TEXT NULL, "strength_experience" TEXT NULL, "training_days" TEXT NOT NULL DEFAULT '', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, "sync_status" TEXT NOT NULL DEFAULT 'local', PRIMARY KEY ("id"));
CREATE TABLE "water_logs" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "milliliters" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "weight_logs" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "weight_kg" REAL NOT NULL, "notes" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "wellbeing_events" ("id" TEXT NOT NULL, "day" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "is_custom_saved" INTEGER NOT NULL DEFAULT 0 CHECK ("is_custom_saved" IN (0, 1)), "notes" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "yoga_sequences" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "poses_json" TEXT NOT NULL, "transition_seconds" INTEGER NOT NULL DEFAULT 5, "style" TEXT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, "deleted_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_activities_started_at ON activities (started_at);
CREATE INDEX idx_activity_samples_activity_id_timestamp_ms ON activity_samples (activity_id, timestamp_ms);
CREATE UNIQUE INDEX idx_daily_checkins_day ON daily_checkins (day);
CREATE INDEX idx_flare_events_day ON flare_events (day);
CREATE INDEX idx_foods_barcode ON foods (barcode);
CREATE INDEX idx_foods_name ON foods (name);
CREATE INDEX idx_nutrition_entries_day ON nutrition_entries (day);
CREATE UNIQUE INDEX idx_recovery_days_day ON recovery_days (day);
CREATE INDEX idx_water_logs_day ON water_logs (day);
CREATE INDEX idx_weight_logs_day ON weight_logs (day);
PRAGMA user_version = 1;
